use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Cloud SDK Authentication Client with rate limiting and retry logic
pub struct AuthClient {
    endpoint: String,
    rate_limiter: Arc<Mutex<RateLimiter>>,
    retry_config: RetryConfig,
    credential_cache: Arc<Mutex<HashMap<String, CachedCredential>>>,
}

struct CachedCredential {
    token: String,
    expires_at: Instant,
}

struct RateLimiter {
    window_start: Instant,
    request_count: u32,
    max_requests_per_window: u32,
    window_duration: Duration,
    failed_attempts: HashMap<String, FailedAttemptRecord>,
}

struct FailedAttemptRecord {
    count: u32,
    first_failure: Instant,
    last_failure: Instant,
    locked_until: Option<Instant>,
}

#[derive(Clone)]
pub struct RetryConfig {
    max_retries: u32,
    base_delay_ms: u64,
    max_delay_ms: u64,
}

#[derive(Debug, PartialEq)]
pub enum AuthError {
    RateLimited,
    InvalidCredentials,
    AccountLocked,
    NetworkError(String),
    InternalError(String),
}

#[derive(Debug)]
pub struct AuthToken {
    pub token: String,
    pub expires_in_secs: u64,
}

impl RateLimiter {
    fn new(max_requests: u32, window: Duration) -> Self {
        RateLimiter {
            window_start: Instant::now(),
            request_count: 0,
            max_requests_per_window: max_requests,
            window_duration: window,
            failed_attempts: HashMap::new(),
        }
    }

    fn check_and_increment(&mut self, identity: &str) -> Result<(), AuthError> {
        let now = Instant::now();

        // Reset window if expired
        if now.duration_since(self.window_start) >= self.window_duration {
            self.window_start = now;
            self.request_count = 0;
        }

        // Check global rate limit
        if self.request_count >= self.max_requests_per_window {
            return Err(AuthError::RateLimited);
        }

        // Check per-identity lockout
        if let Some(record) = self.failed_attempts.get(identity) {
            if let Some(locked_until) = record.locked_until {
                if now < locked_until {
                    return Err(AuthError::AccountLocked);
                }
            }
        }

        self.request_count += 1;
        Ok(())
    }

    fn record_failure(&mut self, identity: &str) {
        let now = Instant::now();
        let record = self.failed_attempts
            .entry(identity.to_string())
            .or_insert(FailedAttemptRecord {
                count: 0,
                first_failure: now,
                last_failure: now,
                locked_until: None,
            });

        // Reset counter if the failure window has passed (5 minutes)
        if now.duration_since(record.first_failure) > Duration::from_secs(300) {
            record.count = 0;
            record.first_failure = now;
        }

        record.count += 1;
        record.last_failure = now;

        // Lock account after 5 failed attempts
        if record.count >= 5 {
            // BUG: lockout duration is calculated from first_failure, not from now
            // This means if attempts are spread across the 5-minute window,
            // the lockout may already be expired or nearly expired by the time it's set
            let lockout_end = record.first_failure + Duration::from_secs(300);
            record.locked_until = Some(lockout_end);
        }
    }

    fn record_success(&mut self, identity: &str) {
        self.failed_attempts.remove(identity);
    }
}

impl AuthClient {
    pub fn new(endpoint: &str) -> Self {
        AuthClient {
            endpoint: endpoint.to_string(),
            rate_limiter: Arc::new(Mutex::new(RateLimiter::new(100, Duration::from_secs(60)))),
            retry_config: RetryConfig {
                max_retries: 3,
                base_delay_ms: 100,
                max_delay_ms: 5000,
            },
            credential_cache: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub fn authenticate(
        &self,
        username: &str,
        password: &str,
    ) -> Result<AuthToken, AuthError> {
        let identity = self.normalize_identity(username);

        // Check rate limiter
        {
            let mut limiter = self.rate_limiter.lock().unwrap();
            limiter.check_and_increment(&identity)?;
        }

        // Check credential cache
        {
            let cache = self.credential_cache.lock().unwrap();
            if let Some(cached) = cache.get(&identity) {
                if Instant::now() < cached.expires_at {
                    return Ok(AuthToken {
                        token: cached.token.clone(),
                        expires_in_secs: cached.expires_at
                            .duration_since(Instant::now())
                            .as_secs(),
                    });
                }
            }
        }

        // Attempt authentication with retry
        let result = self.authenticate_with_retry(&identity, password);

        match &result {
            Ok(token) => {
                let mut limiter = self.rate_limiter.lock().unwrap();
                limiter.record_success(&identity);
                // Cache the credential
                let mut cache = self.credential_cache.lock().unwrap();
                cache.insert(identity, CachedCredential {
                    token: token.token.clone(),
                    expires_at: Instant::now() + Duration::from_secs(token.expires_in_secs),
                });
            }
            Err(AuthError::InvalidCredentials) => {
                let mut limiter = self.rate_limiter.lock().unwrap();
                limiter.record_failure(&identity);
            }
            _ => {}
        }

        result
    }

    fn authenticate_with_retry(
        &self,
        identity: &str,
        password: &str,
    ) -> Result<AuthToken, AuthError> {
        let mut last_error = AuthError::InternalError("no attempts made".to_string());

        for attempt in 0..=self.retry_config.max_retries {
            match self.do_authenticate(identity, password) {
                Ok(token) => return Ok(token),
                Err(AuthError::NetworkError(_)) if attempt < self.retry_config.max_retries => {
                    let delay = std::cmp::min(
                        self.retry_config.base_delay_ms * 2u64.pow(attempt),
                        self.retry_config.max_delay_ms,
                    );
                    std::thread::sleep(Duration::from_millis(delay));
                    last_error = AuthError::NetworkError("retrying".to_string());
                }
                Err(e) => return Err(e),
            }
        }

        Err(last_error)
    }

    fn do_authenticate(&self, identity: &str, password: &str) -> Result<AuthToken, AuthError> {
        // Simulated backend call - in production this would be an HTTP request
        let _ = (&self.endpoint, identity, password);
        Err(AuthError::InvalidCredentials)
    }

    fn normalize_identity(&self, username: &str) -> String {
        username.trim().to_lowercase()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_lockout_after_failures() {
        let client = AuthClient::new("https://auth.example.com");
        for _ in 0..5 {
            let _ = client.authenticate("user@example.com", "wrong");
        }
        let result = client.authenticate("user@example.com", "wrong");
        assert_eq!(result.unwrap_err(), AuthError::AccountLocked);
    }
}
